vendor.models.forEach((m: { modelName: string; name: string }) => {
  const suffix = isPlanModel(m.modelName) ? "（Plan套餐）" : "（按量）";
  m.name = `${m.name.replace(/（Plan）$|（Plan套餐）$|（按量）$/g, "")}${suffix}`;
